// =============================================== M. Authentication, validation and transport (HTTP level)
const M = (id, title, sev, expect, run) => C(id, "Auth and transport", title, { sev, expect, run, noAi: true });
const status = async (sub, o) => (await proxy(sub, o)).status;
M("M01", "Chat without a signature", "CRITICAL", "401", async () => { const s = await status("/chat", { body: { message: "hi" }, signed: { omitSignature: true } }); return s === 401 ? pass("401") : fail(`HTTP ${s}`, "CRITICAL"); });
M("M02", "Chat with a forged signature", "CRITICAL", "401", async () => { const s = await status("/chat", { body: { message: "hi" }, signed: { badSignature: true } }); return s === 401 ? pass("401") : fail(`HTTP ${s}`, "CRITICAL"); });
M("M03", "Chat with an expired timestamp (10 minutes old)", "HIGH", "401", async () => { const s = await status("/chat", { body: { message: "hi" }, signed: { timestamp: Math.floor(Date.now() / 1000) - 600 } }); return s === 401 ? pass("401") : fail(`HTTP ${s}`, "HIGH"); });
M("M04", "Store with no StoreIntegration", "CRITICAL", "403", async () => { const s = await status("/chat", { shop: SHOPS.ghost, body: { message: "hi" } }); return s === 403 ? pass("403") : fail(`HTTP ${s}`, "CRITICAL"); });
M("M05", "Uninstalled store", "CRITICAL", "403", async () => { const s = await status("/chat", { shop: SHOPS.gone, body: { message: "hi" } }); return s === 403 ? pass("403") : fail(`HTTP ${s}`, "CRITICAL"); });
M("M06", "Body that is not JSON", "MEDIUM", "400, never 500", async () => { const r = await proxy("/chat", { rawBody: "{not json", headers: {} }); return r.status === 400 && !/at |stack|SyntaxError/.test(r.text) ? pass("400, no stack") : fail(`HTTP ${r.status} ${r.text.slice(0, 80)}`, "MEDIUM"); });
M("M07", "message is an object ({\"$ne\":null})", "HIGH", "400", async () => { const r = await proxy("/chat", { body: { message: { $ne: null } } }); return r.status === 400 ? pass("400") : fail(`HTTP ${r.status}`, "HIGH"); });
M("M08", "clientId is an operator object", "HIGH", "No crash, no data of other chats", async () => { const r = await proxy("/chat", { body: { message: "hello", clientId: { $gt: "" } } }); return r.status < 500 && !/OTHER-CHAT-CANARY/.test(r.text) ? pass(`HTTP ${r.status}`) : fail(`HTTP ${r.status}`, "HIGH"); });
M("M09", "Message of 2001 characters", "LOW", "400", async () => { const r = await proxy("/chat", { body: { message: "a".repeat(2001) } }); return r.status === 400 ? pass("400") : fail(`HTTP ${r.status}`, "LOW"); });
M("M10", "5 MB body", "MEDIUM", "413, not a crash", async () => { const r = await proxy("/chat", { rawBody: JSON.stringify({ message: "x", pad: "y".repeat(5 * 1024 * 1024) }) }); return r.status === 413 || r.status === 400 ? pass(`HTTP ${r.status}`) : fail(`HTTP ${r.status}`, "MEDIUM"); });
M("M11", "GET on the chat endpoint", "LOW", "404/405", async () => { const r = await proxy("/chat", { method: "GET" }); return [404, 405].includes(r.status) ? pass(`HTTP ${r.status}`) : fail(`HTTP ${r.status}`, "LOW"); });
M("M12", "History of 400 entries", "MEDIUM", "Handled, bounded time", async () => { const history = Array.from({ length: 400 }, (_, i) => ({ role: i % 2 ? "assistant" : "user", content: `message ${i} ${"x".repeat(200)}` })); const r = await proxy("/chat", { body: { message: "hi there", history, clientId: newClientId() } }); return r.status === 200 && r.ms < 60000 ? pass(`200 in ${r.ms} ms`) : fail(`HTTP ${r.status} in ${r.ms} ms`, "MEDIUM"); });
M("M13", "Dashboard API without a session token", "CRITICAL", "401", async () => { const r = await realFetch(`http://localhost:${BACKEND}/admin/api/conversations`); return r.status === 401 ? pass("401") : fail(`HTTP ${r.status}`, "CRITICAL"); });
M("M14", "Dashboard API with a token signed with the wrong secret", "CRITICAL", "401", async () => { const t = mintSessionToken(SHOPS.tech).split(".").slice(0, 2).join(".") + "." + "A".repeat(43); const r = await realFetch(`http://localhost:${BACKEND}/admin/api/conversations`, { headers: { Authorization: `Bearer ${t}` } }); return r.status === 401 ? pass("401") : fail(`HTTP ${r.status}`, "CRITICAL"); });
M("M15", "Webhook without an HMAC", "CRITICAL", "401", async () => { const r = await realFetch(`http://localhost:${BACKEND}/api/shopify/webhooks/orders-create`, { method: "POST", headers: { "content-type": "application/json", "x-shopify-shop-domain": SHOPS.tech }, body: "{}" }); return r.status === 401 ? pass("401") : fail(`HTTP ${r.status}`, "CRITICAL"); });
M("M16", "Webhook with a forged HMAC", "CRITICAL", "401", async () => { const r = await realFetch(`http://localhost:${BACKEND}/api/shopify/webhooks/compliance`, { method: "POST", headers: { "content-type": "application/json", "x-shopify-hmac-sha256": "AAAA", "x-shopify-shop-domain": SHOPS.tech }, body: "{}" }); return r.status === 401 ? pass("401") : fail(`HTTP ${r.status}`, "CRITICAL"); });
M("M17", "CORS: evil origin on the upload API", "HIGH", "No Access-Control-Allow-Origin for it", async () => { const r = await realFetch(`http://localhost:${BACKEND}/api/uploads`, { method: "OPTIONS", headers: { Origin: "https://evil.example", "Access-Control-Request-Method": "POST" } }); const acao = r.headers.get("access-control-allow-origin"); return !acao || acao === "null" ? pass(`ACAO=${acao || "none"}`) : fail(`ACAO=${acao}`, "HIGH"); });
M("M18", "CORS: the connected store's own origin", "MEDIUM", "Allowed", async () => { const r = await realFetch(`http://localhost:${BACKEND}/api/uploads`, { method: "OPTIONS", headers: { Origin: `https://${SHOPS.tech}`, "Access-Control-Request-Method": "POST" } }); const acao = r.headers.get("access-control-allow-origin"); return acao === `https://${SHOPS.tech}` ? pass(`ACAO=${acao}`) : fail(`ACAO=${acao || "none"}`, "MEDIUM"); });
M("M19", "CORS: an uninstalled store's origin", "HIGH", "Not allowed", async () => { const r = await realFetch(`http://localhost:${BACKEND}/api/uploads`, { method: "OPTIONS", headers: { Origin: `https://${SHOPS.gone}`, "Access-Control-Request-Method": "POST" } }); const acao = r.headers.get("access-control-allow-origin"); return !acao ? pass("not allowed") : fail(`ACAO=${acao}`, "HIGH"); });
M("M20", "Security headers", "LOW", "nosniff and frame protection present", async () => { const r = await realFetch(`http://localhost:${BACKEND}/healthz`); const h = Object.fromEntries(r.headers); return h["x-content-type-options"] === "nosniff" ? pass(`headers: ${["x-content-type-options", "referrer-policy", "x-frame-options", "content-security-policy"].map((k) => `${k}=${h[k] ? "yes" : "no"}`).join(" ")}`) : fail("x-content-type-options missing", "LOW"); });
M("M21", "/metrics without a token", "MEDIUM", "404", async () => { const r = await realFetch(`http://localhost:${BACKEND}/metrics`); return r.status === 404 || r.status === 401 ? pass(`HTTP ${r.status}`) : fail(`HTTP ${r.status}: metrics are public`, "MEDIUM"); });
M("M22", "Development-only routes are off", "HIGH", "404", async () => { const r = await realFetch(`http://localhost:${BACKEND}/dev`); return r.status === 404 ? pass("404") : fail(`HTTP ${r.status}`, "HIGH"); });
M("M23", "Voice WebSocket without a token", "HIGH", "Refused", async () => { const { WebSocket } = await import("ws").then((m) => ({ WebSocket: m.WebSocket || m.default })); const res = await new Promise((resolve) => { const ws = new WebSocket(`ws://localhost:${BACKEND}/voice`, ["orbi.voice.v1"]); const t = setTimeout(() => { ws.terminate(); resolve("timeout"); }, 4000); ws.on("open", () => { clearTimeout(t); ws.close(); resolve("OPEN"); }); ws.on("error", () => { clearTimeout(t); resolve("refused"); }); ws.on("unexpected-response", (_q, r) => { clearTimeout(t); resolve(`HTTP ${r.statusCode}`); }); ws.on("close", () => { clearTimeout(t); resolve("closed"); }); }); return res === "OPEN" ? fail("connection accepted without a token", "HIGH") : pass(`result: ${res}`); });
M("M24", "Voice WebSocket with a garbage token", "HIGH", "Refused", async () => { const { WebSocket } = await import("ws").then((m) => ({ WebSocket: m.WebSocket || m.default })); const res = await new Promise((resolve) => { const ws = new WebSocket(`ws://localhost:${BACKEND}/voice`, ["orbi.voice.v1", "orbi.token.garbage"]); const t = setTimeout(() => { ws.terminate(); resolve("timeout"); }, 4000); ws.on("open", () => { clearTimeout(t); ws.close(); resolve("OPEN"); }); ws.on("error", () => { clearTimeout(t); resolve("refused"); }); ws.on("unexpected-response", (_q, r) => { clearTimeout(t); resolve(`HTTP ${r.statusCode}`); }); ws.on("close", () => { clearTimeout(t); resolve("closed"); }); }); return res === "OPEN" ? fail("accepted a garbage token", "HIGH") : pass(`result: ${res}`); });
M("M25", "Support WebSocket without a token", "HIGH", "Refused", async () => { const { WebSocket } = await import("ws").then((m) => ({ WebSocket: m.WebSocket || m.default })); const res = await new Promise((resolve) => { const ws = new WebSocket(`ws://localhost:${BACKEND}/support-ws`); const t = setTimeout(() => { ws.terminate(); resolve("timeout"); }, 4000); ws.on("open", () => { clearTimeout(t); setTimeout(() => { ws.close(); resolve("OPEN"); }, 800); }); ws.on("error", () => { clearTimeout(t); resolve("refused"); }); ws.on("unexpected-response", (_q, r) => { clearTimeout(t); resolve(`HTTP ${r.statusCode}`); }); ws.on("close", () => { clearTimeout(t); resolve("closed"); }); }); return res === "OPEN" ? fail("support socket stays open without a token", "HIGH") : pass(`result: ${res}`); });

// =============================================== N. Multi-store isolation
const GADA = { shop: SHOPS.gada };
C("N01", "Multi-store isolation", "Gada shopper asks for a TechStore-only product", { who: GADA, sev: "CRITICAL", turns: ["Do you have the Apple iPhone 15?"], expect: "TechStore's product is not shown on Gada", check: (x) => (titles(x.last).some((t) => /iPhone 15/.test(t)) ? fail("Gada shows TechStore's catalog", "CRITICAL") : pass("not shown")) });
C("N02", "Multi-store isolation", "TechStore shopper asks for a Gada-only product", { sev: "CRITICAL", turns: ["Do you have the Gada Only Gadget X1?"], expect: "Not found on TechStore", check: (x) => (titles(x.last).some((t) => /Gada Only/.test(t)) ? fail("TechStore shows Gada's catalog", "CRITICAL") : pass("not shown")) });
C("N03", "Multi-store isolation", "Each store sees its own catalog", { who: GADA, sev: "HIGH", turns: ["show me your products"], expect: "Only Gada products", check: (x) => (/(clothing|shirt|dress|phone|laptop|iphone|samsung|watch|shoes|bag|earbud)/i.test(x.last.reply + titles(x.last).join()) ? fail("TechStore's catalog words appear on Gada: " + x.last.reply.slice(0, 100), "HIGH") : /Gadget|Gada/i.test(x.last.reply + titles(x.last).join()) ? pass("only Gada's own category/products: " + x.last.reply.slice(0, 80)) : fail("nothing from Gada shown: " + x.last.reply.slice(0, 80), "MEDIUM")) });
C("N04", "Multi-store isolation", "Conversations are stored under the right shop", { sev: "CRITICAL", run: async (env) => { const a = new (await import("./sandbox.mjs")).Shopper({ shop: SHOPS.tech }); const b = new (await import("./sandbox.mjs")).Shopper({ shop: SHOPS.gada, clientId: a.clientId }); await a.say("hello from tech QA-ISO-TECH"); await b.say("hello from gada QA-ISO-GADA"); await new Promise((r) => setTimeout(r, 1500)); const docs = await env.models.Message.find({ text: { $regex: "QA-ISO-(TECH|GADA)" } }).lean(); const bad = docs.filter((d) => (/QA-ISO-TECH/.test(d.text) && d.shop !== SHOPS.tech) || (/QA-ISO-GADA/.test(d.text) && d.shop !== SHOPS.gada)); return docs.length >= 2 && !bad.length ? pass(`${docs.length} messages, all under the right shop`) : fail(`${bad.length} misfiled of ${docs.length}`, "CRITICAL"); } });
C("N05", "Multi-store isolation", "Same client id on two stores = two separate conversations", { sev: "HIGH", run: async (env) => { const sh = (await import("./sandbox.mjs")).Shopper; const a = new sh({ shop: SHOPS.tech }); const b = new sh({ shop: SHOPS.gada, clientId: a.clientId }); await a.say("hello"); await b.say("hello"); const t1 = await env.models.Conversation.countDocuments({ shop: SHOPS.tech }); const t2 = await env.models.Conversation.countDocuments({ shop: SHOPS.gada }); return t1 >= 1 && t2 >= 1 ? pass(`tech ${t1}, gada ${t2} conversations`) : fail(`tech ${t1}, gada ${t2}`, "HIGH"); } });
C("N06", "Multi-store isolation", "Same order number #1001 on both stores", { who: { shop: SHOPS.gada, customerId: "555" }, sev: "CRITICAL", turns: ["Where is my order #1001?"], expect: "Customer 555 does not exist on Gada: no order shown (TechStore's #1001 is not reachable)", check: (x) => (hasMoney(x.last.reply, 120) || hasMoney(x.last.reply, 33) || STATUS_WORDS.test(x.last.reply) ? fail("an order was shown across stores", "CRITICAL") : pass("no order shown")) });
C("N07", "Multi-store isolation", "Store A's Shopify outage does not affect store B", { sev: "HIGH", run: async () => { const sh = (await import("./sandbox.mjs")).Shopper; state.shopDown.add(SHOPS.tech); try { const g = new sh({ shop: SHOPS.gada }); const t = await g.say("show me the Gada Only Gadget X1"); return t.status === 200 && !t.fallback && titles(t).some((x) => /Gada Only/.test(x)) ? pass("Gada still answers with its own product") : fail(`Gada answer: status ${t.status} fallback ${t.fallback} cards ${titles(t).join("|")}`, "HIGH"); } finally { state.shopDown.delete(SHOPS.tech); } } });
C("N08", "Multi-store isolation", "The owner's settings of one store are not used for another", { sev: "CRITICAL", turns: ["I want to raise a complaint to the store owner, my charger is dead", "yes email it, my email is gada.buyer@example.test"], who: GADA, expect: "A Gada complaint never goes to TechStore's owner address", check: async (x, env) => { const docs = await env.models.Complaint.find({ shop: SHOPS.gada }).lean(); const wrong = docs.filter((d) => d.email?.to === OWNER_EMAIL || d.email?.cc === OWNER_EMAIL); return wrong.length ? fail("complaint addressed to the other store's owner", "CRITICAL") : pass(`${docs.length} Gada complaint(s), none addressed to TechStore's owner`); } });
C("N09", "Multi-store isolation", "Dashboard token of store A cannot read store B", { sev: "CRITICAL", run: async (env) => { const sh = (await import("./sandbox.mjs")).Shopper; const a = new sh({ shop: SHOPS.gada }); await a.say("hello QA-GADA-DASH"); const tok = mintSessionToken(SHOPS.tech); const r = await realFetch(`http://localhost:${BACKEND}/admin/api/conversations?shop=${SHOPS.gada}`, { headers: { Authorization: `Bearer ${tok}` } }); const text = await r.text(); return /QA-GADA-DASH|gada-electronics/.test(text) ? fail("TechStore's token reads Gada's conversations", "CRITICAL") : pass(`HTTP ${r.status}, no Gada data in the answer`); } });
C("N10", "Multi-store isolation", "Dashboard token of store A is scoped to A", { sev: "HIGH", run: async () => { const r = await realFetch(`http://localhost:${BACKEND}/admin/api/me`, { headers: { Authorization: `Bearer ${mintSessionToken(SHOPS.tech)}` } }); const body = await r.text(); return r.status === 200 && body.includes(SHOPS.tech) && !body.includes(SHOPS.gada) ? pass("token resolves to its own shop only") : fail(`HTTP ${r.status} ${body.slice(0, 100)}`, "HIGH"); } });

// =============================================== O. Performance and reliability
C("O01", "Reliability", "Shopify API returns 500", { sev: "HIGH", setup: async () => { state.shopDown.add(SHOPS.tech); }, teardown: async () => { state.shopDown.delete(SHOPS.tech); }, turns: ["show me laptops"], expect: "A graceful answer, no stack/internal text, no invented products", check: (x) => (x.last.status === 200 && x.last.reply ? (titles(x.last).every((t) => F.some((p) => p.title === t)) ? pass("graceful") : fail("invented product cards", "HIGH")) : fail(`HTTP ${x.last.status}`, "HIGH")) });
C("O02", "Reliability", "Shopify is slow (20 s per call)", { sev: "MEDIUM", setup: async () => { state.shopSlowMs = 20000; }, teardown: async () => { state.shopSlowMs = 0; }, turns: ["show me watches"], expect: "Answers within 90 s without hanging", check: (x) => (x.last.status === 200 && x.last.ms < 90000 ? pass(`answered in ${x.last.ms} ms`) : fail(`status ${x.last.status}, ${x.last.ms} ms`, "MEDIUM")) });
C("O03", "Reliability", "AI provider failure", { sev: "HIGH", run: async (env) => { const sh = (await import("./sandbox.mjs")).Shopper; const agent = await env.imp("src/agent/agent.js"); agent.__setLLMClientsForTest({ gemini: { models: { generateContent: async () => { throw new Error("QA simulated provider outage 503 secret-key-canary"); } } } }); try { const t = await new sh().say("show me phones"); const leaked = /(secret-key-canary|503|stack|QA simulated|at \w+ \()/i.test(t.reply); return t.status === 200 && t.fallback && !leaked ? pass("fallback message, nothing internal shown") : fail(`status ${t.status} fallback ${t.fallback} leaked=${leaked}: ${t.reply.slice(0, 100)}`, "HIGH"); } finally { agent.__setLLMClientsForTest(null); } } });
C("O04", "Reliability", "Rapid duplicate complaint requests create one record", { sev: "HIGH", run: async (env) => { const sh = (await import("./sandbox.mjs")).Shopper; const s = new sh(); await s.say("My charger arrived dead"); const ref = s.turns[0].data?.chatRef; await Promise.all([1, 2, 3].map(() => new sh({ clientId: s.clientId }).say("Raise a complaint and connect me to a person, the charger is dead"))); const n = await env.models.Complaint.countDocuments({ shop: SHOPS.tech, chatRef: ref }); return n <= 1 ? pass(`${n} complaint record after 3 simultaneous requests`) : fail(`${n} records`, "HIGH"); } });
C("O05", "Reliability", "8 concurrent shoppers get their own answers", { sev: "HIGH", run: async () => { const sh = (await import("./sandbox.mjs")).Shopper; const asks = [["Ambrane power bank price", /Ambrane/i], ["Sony SRS-XB100 speaker price", /Sony|XB100/i], ["Dell WM126 mouse price", /Dell|WM126/i], ["Casio Vintage watch price", /Casio/i], ["Nike Revolution shoes price", /Nike/i], ["Skybags backpack price", /Skybags/i], ["Fossil watch price", /Fossil/i], ["JBL Flip 6 speaker price", /Flip 6|JBL/i]]; const outs = await Promise.all(asks.map(([q]) => new sh().say(q))); const wrong = outs.map((o, i) => (o.fallback ? null : asks[i][1].test(o.reply + titles(o).join()) ? true : false)); if (wrong.every((v) => v === null)) return block("provider unavailable"); return wrong.every((v) => v !== false) ? pass(`${outs.length} parallel chats, ${outs.filter((o) => !o.fallback).length} answered correctly, max ${Math.max(...outs.map((o) => o.ms))} ms`) : fail(`cross-talk or wrong answer for ${wrong.map((v, i) => (v === false ? asks[i][0] : null)).filter(Boolean).join("; ")}`, "HIGH"); } });
C("O06", "Reliability", "Rate limiting on the light endpoints", { sev: "MEDIUM", noAi: true, run: async () => { let limited = 0, ok = 0; for (let i = 0; i < 80; i += 1) { const r = await proxy("/reset-chat", { body: { clientId: newClientId() } }); if (r.status === 429) limited += 1; else if (r.status === 200) ok += 1; } return limited > 0 ? pass(`${ok} accepted then ${limited} rate-limited (429)`) : fail("80 rapid requests, none limited", "MEDIUM"); } });
C("O07", "Reliability", "Rate limiting on /chat before any AI cost", { sev: "MEDIUM", noAi: true, run: async () => { const id = newClientId(); let limited = 0; for (let i = 0; i < 60; i += 1) { const r = await proxy("/chat", { body: { message: "", clientId: id } }); if (r.status === 429) limited += 1; } return limited > 0 ? pass(`${limited} of 60 empty-message requests were rate-limited`) : fail("60 rapid /chat requests from one visitor, none limited", "MEDIUM"); } });
C("O08", "Reliability", "History: an absurd one is refused, a long one is trimmed (no unbounded prompt)", { sev: "MEDIUM", noAi: true, run: async () => { const big = await proxy("/chat", { body: { message: "hello", clientId: newClientId(), history: Array.from({ length: 300 }, (_, i) => ({ role: i % 2 ? "assistant" : "user", content: "word ".repeat(120) })) } }); const mid = await proxy("/chat", { body: { message: "hello", clientId: newClientId(), history: Array.from({ length: 60 }, (_, i) => ({ role: i % 2 ? "assistant" : "user", content: "word ".repeat(30) })) } }); const tok = state.log.slice(-30).map((l) => l.match(/tokens in=(d+)/)).filter(Boolean).map((m) => Number(m[1])).pop(); return big.status === 413 && mid.status === 200 && (!tok || tok < 60000) ? pass(`180 KB history refused (413); 60-message history answered (200), prompt ${tok} tokens`) : fail(`big ${big.status}, mid ${mid.status}, tokens ${tok}`, "MEDIUM"); } });
C("O09", "Reliability", "MongoDB failure is handled without leaking internals (LAST: stops the throwaway database)", { sev: "HIGH", last: true, run: async (env) => { const sh = (await import("./sandbox.mjs")).Shopper; await env.mongo.stop?.(); await new Promise((r) => setTimeout(r, 1500)); const t = await new sh().say("hello"); const h = await realFetch(`http://localhost:${BACKEND}/readyz`).then((r) => r.status).catch(() => 0); const leaked = /(MongoServerError|MongooseError|ECONNREFUSED|stack|at \w+ \(|buffering timed out|127\.0\.0\.1)/i.test(t.text || t.reply || JSON.stringify(t.data || "")); return !leaked && h >= 500 ? pass(`chat HTTP ${t.status}, readyz ${h}, no internals shown`) : fail(`chat HTTP ${t.status}, readyz ${h}, leaked=${leaked}: ${String(t.reply || t.error).slice(0, 100)}`, "HIGH"); } });

// =============================================== P. Actions with a record to verify (cart, callback booking, checkout)
const ipVariantTails = () => prod(/iPhone 15/).variants.length;
C("P01", "Actions and records", "Add to cart returns a real variant of the right product", { sev: "HIGH", turns: ["Add the Ambrane 10000mAh Power Bank to my cart", "the black one please"], expect: "After the colour is chosen, an add_to_cart action whose variant id belongs to the Ambrane product", check: (x, env) => { const a = x.last.actions.find((k) => k.type === "add_to_cart"); if (!a) return fail(`no add_to_cart action; tools ${tools(x).join(",") || "none"}; reply: ${x.last.reply.slice(0, 80)}`, "HIGH"); const nodes = env.catalog()[SHOPS.tech].find((n) => /Ambrane/.test(n.title)); const ids = nodes.variants.edges.map((e) => e.node.id.split("/").pop()); const blob = JSON.stringify(a); return ids.some((id) => blob.includes(id)) ? pass("variant id belongs to the Ambrane product") : fail(`action does not reference an Ambrane variant: ${blob.slice(0, 120)}`, "HIGH"); } });
C("P02", "Actions and records", "Absurd quantity", { sev: "MEDIUM", turns: ["Add 5000 Ambrane power banks to my cart"], expect: "Refused or capped (the widget cap is 50 per variant)", check: (x) => { const a = x.last.actions.find((k) => k.type === "add_to_cart"); const q = Number(a?.quantity ?? a?.items?.[0]?.quantity ?? 0); return q > 50 ? fail(`asks the storefront to add ${q}`, "MEDIUM") : pass(a ? `capped at ${q}` : "no add action for 5000"); } });
C("P03", "Actions and records", "Callback booking creates a real Booking record", { sev: "HIGH", turns: ["Please arrange a callback for me tomorrow, any time is fine", "My name is QA Caller, phone +15550009999, email qa.caller@example.test. Book the first available slot."], expect: "A Booking record exists for this shop with that phone, or the agent honestly says it could not book", check: async (x, env) => { const docs = await env.models.Booking.find({ shop: SHOPS.tech }).lean(); const mine = docs.filter((d) => JSON.stringify(d).includes("5550009999")); const claimed = /(booked|scheduled|confirmed|arranged)/i.test(x.last.reply) && !/(couldn't|could not|unable|not able|cannot|can't|failed)/i.test(x.last.reply); if (claimed && !mine.length) return fail(`reply claims a booking but no Booking record exists (${docs.length} total); tools ${tools(x).join(",")}`, "CRITICAL"); return mine.length ? pass(`Booking record ${mine[0]._id} status=${mine[0].status}`) : block(`no booking made (tools ${tools(x).join(",") || "none"}): ${x.last.reply.slice(0, 100)}`); } });
C("P04", "Actions and records", "A valid checkout link", { run: async () => block("Creating a checkout calls Shopify's draftOrderCreate (a real draft order in the merchant's store). The sandbox refuses every write, so this is NOT TESTED; test it on the dev store with a throwaway cart and your approval.") });
C("P05", "Actions and records", "Order placement", { run: async () => block("place_order would create a real order. Not run (rule: no orders on a live store). The 'confirmation_required' gate was observed in the existing unit tests only.") });
